fn native_keys_to_window_key_sample<I>(keys: I) -> NativeWindowKeySample
where
    I: IntoIterator<Item = Key>,
{
    let mut sample = NativeWindowKeySample::default();
    for key in keys {
        native_window_key_sample_add_key(&mut sample, key);
    }
    sample
}

fn native_window_key_sample_add_key(sample: &mut NativeWindowKeySample, key: Key) {
    match key {
        Key::Enter => sample.enter = true,
        Key::Escape => sample.escape = true,
        _ => {
            sample.buttons = merge_action_buttons(sample.buttons, native_keys_to_buttons([key]));
        }
    }
}

fn native_keys_to_buttons<I>(keys: I) -> ActionButtons
where
    I: IntoIterator<Item = Key>,
{
    let mut buttons = ActionButtons::default();
    for key in keys {
        match key {
            Key::Enter => {}
            Key::P => buttons.start = true,
            Key::C => buttons.coin = true,
            Key::V => buttons.service = true,
            Key::Up => buttons.up = true,
            Key::Down => buttons.down = true,
            Key::Left => buttons.left = true,
            Key::Right => buttons.right = true,
            Key::Z | Key::Space => buttons.punch = true,
            Key::X => buttons.kick = true,
            Key::Q | Key::L | Key::B => buttons.beast = true,
            Key::E | Key::F | Key::G | Key::H => buttons.guard = true,
            Key::W => buttons.p2_up = true,
            Key::S => buttons.p2_down = true,
            Key::A => buttons.p2_left = true,
            Key::D => buttons.p2_right = true,
            Key::J => buttons.p2_punch = true,
            Key::K => buttons.p2_kick = true,
            Key::U => buttons.p2_beast = true,
            Key::I => buttons.p2_guard = true,
            Key::O => buttons.p2_start = true,
            Key::N => buttons.p2_coin = true,
            _ => {}
        }
    }
    buttons
}

fn merge_action_buttons(a: ActionButtons, b: ActionButtons) -> ActionButtons {
    ActionButtons {
        start: a.start || b.start,
        coin: a.coin || b.coin,
        service: a.service || b.service,
        up: a.up || b.up,
        down: a.down || b.down,
        left: a.left || b.left,
        right: a.right || b.right,
        punch: a.punch || b.punch,
        kick: a.kick || b.kick,
        beast: a.beast || b.beast,
        guard: a.guard || b.guard,
        p2_start: a.p2_start || b.p2_start,
        p2_coin: a.p2_coin || b.p2_coin,
        p2_up: a.p2_up || b.p2_up,
        p2_down: a.p2_down || b.p2_down,
        p2_left: a.p2_left || b.p2_left,
        p2_right: a.p2_right || b.p2_right,
        p2_punch: a.p2_punch || b.p2_punch,
        p2_kick: a.p2_kick || b.p2_kick,
        p2_beast: a.p2_beast || b.p2_beast,
        p2_guard: a.p2_guard || b.p2_guard,
    }
}

fn parse_native_window_scale(value: Option<String>) -> Result<Scale, String> {
    match value
        .as_deref()
        .unwrap_or("1")
        .to_ascii_lowercase()
        .as_str()
    {
        "1" | "x1" => Ok(Scale::X1),
        "2" | "x2" => Ok(Scale::X2),
        "4" | "x4" => Ok(Scale::X4),
        "8" | "x8" => Ok(Scale::X8),
        "fit" | "fitscreen" | "fit-screen" => Ok(Scale::FitScreen),
        value => Err(format!(
            "native window scale must be one of 1, 2, 4, 8, or fit: {value}"
        )),
    }
}

