fn native_warning_skip_to_title_script() -> Vec<NativeScriptSegment> {
    let mut segments = vec![
        NativeScriptSegment {
            action: Action::Noop,
            frames: NATIVE_WARNING_SKIP_INITIAL_FRAMES,
        },
        NativeScriptSegment {
            action: Action::Start,
            frames: NATIVE_WARNING_SKIP_PULSE_FRAMES,
        },
        NativeScriptSegment {
            action: Action::Noop,
            frames: NATIVE_WARNING_SKIP_GAP_FRAMES,
        },
        NativeScriptSegment {
            action: Action::Punch,
            frames: NATIVE_WARNING_SKIP_PULSE_FRAMES,
        },
        NativeScriptSegment {
            action: Action::Noop,
            frames: NATIVE_WARNING_SKIP_GAP_FRAMES,
        },
        NativeScriptSegment {
            action: Action::Start,
            frames: NATIVE_WARNING_SKIP_PULSE_FRAMES,
        },
        NativeScriptSegment {
            action: Action::Noop,
            frames: NATIVE_WARNING_SKIP_GAP_FRAMES,
        },
    ];

    // BR2 has multiple independently skippable warning and intro phases.
    // Released retry pulses let whichever phase is currently polling advance;
    // without credit they remain harmless once the title has been reached.
    for _ in 0..NATIVE_WARNING_SKIP_RETRY_CYCLES {
        segments.extend([
            NativeScriptSegment {
                action: Action::Start,
                frames: NATIVE_WARNING_SKIP_PULSE_FRAMES,
            },
            NativeScriptSegment {
                action: Action::Noop,
                frames: NATIVE_WARNING_SKIP_RETRY_GAP_FRAMES,
            },
            NativeScriptSegment {
                action: Action::Punch,
                frames: NATIVE_WARNING_SKIP_PULSE_FRAMES,
            },
            NativeScriptSegment {
                action: Action::Noop,
                frames: NATIVE_WARNING_SKIP_RETRY_GAP_FRAMES,
            },
        ]);
    }

    segments.push(NativeScriptSegment {
        action: Action::Noop,
        frames: NATIVE_PLAY_TITLE_ENTRY_FRAMES,
    });
    segments
}

fn native_script_segment_is_credit_attempt(segment: NativeScriptSegment) -> bool {
    matches!(
        segment.action,
        Action::Coin | Action::CoinStart | Action::Service
    )
}

fn native_play_boot_wait_segments(segments: &[NativeScriptSegment]) -> Vec<NativeScriptSegment> {
    segments
        .iter()
        .copied()
        .take_while(|segment| !native_script_segment_is_credit_attempt(*segment))
        .collect()
}

