    fn native_play_gui_defaults_to_sixty_presented_frames_per_second() {
        assert_eq!(super::NATIVE_PLAY_GUI_DISPLAY_REFRESH_FRAMES, 1);
    }

    fn test_gradient_playfield_frame() -> NativeDisplayFrame {
        let width = 640;
        let height = 480;
        let mut pixels = vec![0; width * height];
        for y in 0..height {
            for x in 0..width {
                let red = 24 + ((x * 17 + y * 5) % 176) as u32;
                let green = 40 + ((x * 7 + y * 19) % 184) as u32;
                let blue = 32 + ((x * 13 + y * 11) % 192) as u32;
                pixels[y * width + x] = (red << 16) | (green << 8) | blue;
            }
        }
        NativeDisplayFrame {
            width,
            height,
            pixels,
        }
    }

    fn test_warning_text_overlay_over_playfield_frame() -> NativeDisplayFrame {
        let width = 640;
        let mut frame = test_gradient_playfield_frame();

        for y in 0..120 {
            for x in 0..width {
                frame.pixels[y * width + x] = 0;
            }
        }
        for y in 120..176 {
            for x in 0..320 {
                frame.pixels[y * width + x] = 0;
            }
        }
        for y in 48..108 {
            for x in (44..304).step_by(16) {
                for stroke_x in x..(x + 7).min(width) {
                    frame.pixels[y * width + stroke_x] = 0x00f0_f0e8;
                }
            }
        }
        for y in (52..112).step_by(12) {
            for x in 44..304 {
                if x % 5 != 0 {
                    frame.pixels[y * width + x] = 0x00e8_e8e0;
                }
            }
        }

        frame
    }

    fn test_low_palette_gpu_verified_stage_frame() -> NativeDisplayFrame {
        let width = 640;
        let height = 480;
        let palette = [
            0x0010_1828,
            0x0018_2030,
            0x0020_3050,
            0x0030_2048,
            0x0040_3020,
            0x0060_4028,
            0x0080_6038,
            0x0028_8050,
            0x0048_6088,
            0x0060_7040,
            0x0078_8050,
            0x0020_70b0,
            0x0030_8058,
            0x0040_9050,
            0x0058_6840,
            0x0068_7850,
            0x0078_8860,
            0x0028_4868,
            0x0038_5878,
            0x0048_6888,
            0x0058_7898,
            0x0068_88a8,
            0x0078_98b8,
            0x0088_a8c8,
            0x0098_b8d8,
            0x0028_7040,
            0x0038_8050,
            0x0048_9060,
            0x0058_a070,
            0x0068_b080,
            0x0078_c090,
            0x0088_d0a0,
            0x0098_e0b0,
            0x0030_4050,
            0x0040_5060,
            0x0050_6070,
            0x0060_7080,
            0x0070_8090,
        ];
        let mut pixels = vec![0; width * height];
        for y in 42..380 {
            for x in 0..width {
                if (x / 8 + y / 8 + (x * y) / 8192) % 10 < 4 {
                    continue;
                }
                let index = (x / 8 + y / 6 + (x * y) / 4096) % palette.len();
                pixels[y * width + x] = palette[index];
            }
        }

        NativeDisplayFrame {
            width,
            height,
            pixels,
        }
    }

    fn test_low_palette_logo_transition_frame() -> NativeDisplayFrame {
        let width = 640;
        let height = 480;
        let mut pixels = vec![0; width * height];
        for y in 0..height {
            for x in 0..width {
                let color = if (x + y * 3) % 10 == 0 {
                    0
                } else if x < y.saturating_mul(width) / height / 2 {
                    0x0066_6600
                } else if x >= width / 2 {
                    let shade = ((x / 8 + y / 6) % 72) as u32;
                    ((64 + shade) << 16) | ((shade / 3) << 8)
                } else {
                    let shade = ((x / 9 + y / 7) % 56) as u32;
                    ((48 + shade) << 16) | ((shade / 4) << 8)
                };
                pixels[y * width + x] = color;
            }
        }

        NativeDisplayFrame {
            width,
            height,
            pixels,
        }
    }

