    #[test]
    fn scripted_action_advances_across_segments() {
        let segments = vec![
            NativeScriptSegment {
                action: Action::Coin,
                frames: 2,
            },
            NativeScriptSegment {
                action: Action::Start,
                frames: 1,
            },
        ];
        let mut segment_index = 0;
        let mut segment_frame = 0;

        assert_eq!(
            next_scripted_action(&segments, &mut segment_index, &mut segment_frame),
            Some(Action::Coin)
        );
        assert_eq!(
            next_scripted_action(&segments, &mut segment_index, &mut segment_frame),
            Some(Action::Coin)
        );
        assert_eq!(
            next_scripted_action(&segments, &mut segment_index, &mut segment_frame),
            Some(Action::Start)
        );
        assert!(native_script_completed(
            &segments,
            segment_index,
            segment_frame
        ));
        assert_eq!(
            next_scripted_action(&segments, &mut segment_index, &mut segment_frame),
            None
        );
        assert!(native_script_completed(
            &segments,
            segment_index,
            segment_frame
        ));
    }

    #[test]
    fn native_input_latch_preserves_brief_button_across_guest_frames() {
        let mut latch = NativeInputLatch::default();
        let start = ActionButtons {
            start: true,
            ..ActionButtons::default()
        };

        assert_eq!(latch.buttons(start), start);
        for _ in 0..32 {
            assert_eq!(latch.buttons(ActionButtons::default()), start);
        }
        for _ in 0..super::NATIVE_PLAY_INPUT_LATCH_FRAMES - 1 {
            latch.advance_frame();
            assert_eq!(latch.buttons(ActionButtons::default()), start);
        }
        latch.advance_frame();

        assert_eq!(
            latch.buttons(ActionButtons::default()),
            ActionButtons::default()
        );
    }

    #[test]
    fn native_input_latch_restarts_for_a_new_press() {
        let mut latch = NativeInputLatch::default();
        let right = ActionButtons {
            right: true,
            ..ActionButtons::default()
        };
        let punch = ActionButtons {
            punch: true,
            ..ActionButtons::default()
        };

        assert_eq!(latch.buttons(right), right);
        for _ in 0..32 {
            assert_eq!(latch.buttons(ActionButtons::default()), right);
        }
        latch.advance_frame();

        assert_eq!(
            latch.buttons(punch),
            ActionButtons {
                right: true,
                punch: true,
                ..ActionButtons::default()
            }
        );
        for _ in 0..super::NATIVE_PLAY_INPUT_LATCH_FRAMES - 2 {
            latch.advance_frame();
            assert_eq!(
                latch.buttons(ActionButtons::default()),
                ActionButtons {
                    right: true,
                    punch: true,
                    ..ActionButtons::default()
                }
            );
        }
        latch.advance_frame();
        assert_eq!(latch.buttons(ActionButtons::default()), punch);
        latch.advance_frame();
        assert_eq!(
            latch.buttons(ActionButtons::default()),
            ActionButtons::default()
        );
    }

