    #[test]
    fn native_play_gui_idle_fast_path_allows_only_quiet_uninstrumented_frames() {
        let mut input_latch = NativeInputLatch::default();
        let mut physical_latch = NativeInputLatch::default();
        let physical_enter = super::NativePhysicalEnterSequencer::default();
        let trace = NativeGuiInputTrace::disabled(NativeInputActivity::default());
        let script = NativeGuiTestInputScript::default();
        let sample = NativeWindowButtonSample::default();

        assert!(native_play_gui_idle_fast_path_allowed(
            None,
            &input_latch,
            &physical_latch,
            &physical_enter,
            &trace,
            &script,
            false,
            sample,
        ));

        let enabled_trace = NativeGuiInputTrace::enabled(NativeInputActivity::default());
        assert!(!native_play_gui_idle_fast_path_allowed(
            None,
            &input_latch,
            &physical_latch,
            &physical_enter,
            &enabled_trace,
            &script,
            false,
            sample,
        ));

        let scripted = NativeGuiTestInputScript::from_segments(&[NativeScriptSegment {
            action: Action::Noop,
            frames: 1,
        }]);
        assert!(!native_play_gui_idle_fast_path_allowed(
            None,
            &input_latch,
            &physical_latch,
            &physical_enter,
            &trace,
            &scripted,
            false,
            sample,
        ));

        let mut completed_script = scripted.clone();
        completed_script.advance_frame();
        assert!(completed_script.is_complete());
        assert!(!native_play_gui_idle_fast_path_allowed(
            None,
            &input_latch,
            &physical_latch,
            &physical_enter,
            &trace,
            &completed_script,
            false,
            sample,
        ));
        completed_script.advance_frame();
        assert!(native_play_gui_idle_fast_path_allowed(
            None,
            &input_latch,
            &physical_latch,
            &physical_enter,
            &trace,
            &completed_script,
            false,
            sample,
        ));

        assert!(!native_play_gui_idle_fast_path_allowed(
            Some(Action::Noop),
            &input_latch,
            &physical_latch,
            &physical_enter,
            &trace,
            &script,
            false,
            sample,
        ));

        assert!(!native_play_gui_idle_fast_path_allowed(
            None,
            &input_latch,
            &physical_latch,
            &physical_enter,
            &trace,
            &script,
            true,
            sample,
        ));

        let pressed_sample = NativeWindowButtonSample {
            minifb: Action::Left.buttons(),
            merged: Action::Left.buttons(),
            ..NativeWindowButtonSample::default()
        };
        assert!(!native_play_gui_idle_fast_path_allowed(
            None,
            &input_latch,
            &physical_latch,
            &physical_enter,
            &trace,
            &script,
            false,
            pressed_sample,
        ));

        let quit_sample = NativeWindowButtonSample {
            quit_requested: true,
            ..NativeWindowButtonSample::default()
        };
        assert!(!native_play_gui_idle_fast_path_allowed(
            None,
            &input_latch,
            &physical_latch,
            &physical_enter,
            &trace,
            &script,
            false,
            quit_sample,
        ));

        input_latch.buttons(Action::Start.buttons());
        assert!(!native_play_gui_idle_fast_path_allowed(
            None,
            &input_latch,
            &physical_latch,
            &physical_enter,
            &trace,
            &script,
            false,
            sample,
        ));

        input_latch.clear();
        physical_latch.buttons(Action::Right.buttons());
        assert!(!native_play_gui_idle_fast_path_allowed(
            None,
            &input_latch,
            &physical_latch,
            &physical_enter,
            &trace,
            &script,
            false,
            sample,
        ));
    }

    #[test]
    fn native_gui_test_input_script_parses_segment_and_frame_tokens() {
        let segments = parse_native_gui_test_input_script("punch:2, noop ; right+punch")
            .expect("test input script parses");
        assert_eq!(
            segments,
            vec![
                NativeScriptSegment {
                    action: Action::Punch,
                    frames: 2,
                },
                NativeScriptSegment {
                    action: Action::Noop,
                    frames: 1,
                },
                NativeScriptSegment {
                    action: Action::RightPunch,
                    frames: 1,
                },
            ]
        );

        let mut script = NativeGuiTestInputScript::from_segments(&segments);
        assert_eq!(script.len(), 4);
        assert!(!script.is_complete());
        assert_eq!(
            script.requested_buttons(),
            ActionButtons {
                right: true,
                punch: true,
                ..ActionButtons::default()
            }
        );
        assert_eq!(script.current_buttons(), Action::Punch.buttons());
        script.advance_frame();
        assert_eq!(script.current_buttons(), Action::Punch.buttons());
        script.advance_frame();
        assert_eq!(script.current_buttons(), ActionButtons::default());
        script.advance_frame();
        assert_eq!(script.current_buttons(), Action::RightPunch.buttons());
        script.advance_frame();
        assert_eq!(script.current_buttons(), ActionButtons::default());
        assert!(script.is_complete());
    }

